INSERT INTO "leadership_skills" ("skill_id", "name", "description") VALUES ("1", "Strategic Thinking", "Developing a vision of where yu want to be");
INSERT INTO "leadership_skills" ("skill_id", "name", "description") VALUES ("2", "Planning", "These areas are key management skills, but the best leaders will also be able to turn their hand to these. The best vision in the world is no good without the plan to turn it into reality.");
INSERT INTO "leadership_skills" ("skill_id", "name", "description") VALUES ("3", "People Management Skills", "Without followers, there are no leaders. Leaders therefore need skills in working with others on a one-to-one and group basis, and a range of tools in their armoury to deal with a wide range of situations.");
INSERT INTO "leadership_skills" ("skill_id", "name", "description") VALUES ("4", "Change Management and Innovation Skills", "A leader needs to understand change management in order to lead an organisation through the process.");
INSERT INTO "leadership_skills" ("skill_id", "name", "description") VALUES ("5", "Communication Skills", "While communication skills are important for everyone, leaders and managers perhaps need them even more.");
INSERT INTO "leadership_skills" ("skill_id", "name", "description") VALUES ("6", "Persuasion and Influencing Skills", "Good leaders use a range of tools for persuading and influencing others.");
